    KeyCloseIcon.AnchorPoint = Vector2.new(0.5, 0.5)
    KeyCloseIcon.BackgroundTransparency = 1
    KeyCloseIcon.Position = UDim2.new(0.5, 0, 0.5, 0)
    KeyCloseIcon.Size = UDim2.new(1, -8, 1, -8)
