                    if ToggleConfig.Title2 ~= "" then
                        Toggle.Size = UDim2.new(Toggle.Size.X.Scale, Toggle.Size.X.Offset, 0,
                            ToggleContent.AbsoluteSize.Y + 47)
                    else
                        Toggle.Size = UDim2.new(Toggle.Size.X.Scale, Toggle.Size.X.Offset, 0,
