                    local updatingFields = false

                    local function RefreshUI(skipFields)
                        editColor = Color3.fromHSV(editH, editS, editV)
                        SVBox.BackgroundColor3 = Color3.fromHSV(editH, 1, 1)
                        SVCursor.Position = UDim2.new(editS, 0, 1 - editV, 0)
