                    if asset:match("^rbxassetid://") or asset:match("^rbxasset://") or asset:match("^rbxthumb://") or asset:match("^%d+$") then
                        ApplyIcon(Img, asset, 512)
                        LoadingLabel:Destroy()
                    else
